<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { applicationService, statusLabels, type Application, type ApplicationInput } from '@/services/applications'
import AppModal from '@/components/AppModal.vue'
import { demoMode } from '@/services/quality'
const route = useRoute(); const router = useRouter(); const items = ref<Application[]>([]); const loading = ref(true); const error = ref(''); const busy = ref(false); const editing = ref(false)
const selectedId = ref(Number(route.query.id) || 0)
const selected = computed(() => items.value.find(a => a.id === selectedId.value) || items.value[0])
const form = reactive<ApplicationInput>({ officine_name: '', phone: '', city: '', address: '', applicant_function: '', consent: false })
async function load() { loading.value = true; error.value = ''; try { items.value = await applicationService.list() } catch(e) { error.value = (e as Error).message } finally { loading.value = false } }
function edit() { const a = selected.value; if (!a) return; Object.assign(form, { officine_name: a.name, phone: a.phone, city: a.city, address: a.address, applicant_function: a.applicant_function, consent: false }); editing.value = true }
async function save() { if (!selected.value) return; busy.value = true; error.value = ''; try { await applicationService.resubmit(selected.value.id, form); editing.value = false; await load() } catch(e) { error.value = (e as Error).message } finally { busy.value = false } }
function enter() { if (!selected.value || selected.value.status !== 'active') return; if (!demoMode) sessionStorage.setItem('bestpharma.officine', String(selected.value.id)); router.push('/dashboard') }
onMounted(load)
</script>
<template><div class="page"><div class="page-heading compact"><div><p class="eyebrow">OUVERTURE DE VOTRE ESPACE</p><h1>Votre dossier,<br><span class="accent-serif">étape par étape.</span></h1><p class="page-subtitle">Suivez l’instruction de votre demande par l’équipe BEG.</p></div><button class="button secondary" :disabled="loading || busy" @click="load">Actualiser le suivi</button></div><div v-if="error && !editing" role="alert" class="alert error">{{ error }}</div><p v-if="loading" class="loading">Chargement du dossier…</p><section v-else-if="!selected" class="panel empty-state"><h2>Aucun dossier soumis</h2><p>Créez votre demande pour commencer.</p><RouterLink class="button primary" to="/register">Ouvrir une officine</RouterLink></section><template v-else><label v-if="items.length > 1" class="application-selector">Dossier à consulter<select v-model="selectedId" @change="editing = false"><option v-for="a in items" :key="a.id" :value="a.id">{{ a.name }}</option></select></label><section class="panel application-card"><div class="panel-heading"><div><p class="eyebrow">DOSSIER #{{ String(selected.id).padStart(4,'0') }}</p><h2>{{ selected.name }}</h2></div><span class="status-badge" :class="selected.status">{{ statusLabels[selected.status] }}</span></div><div class="form-body"><div class="application-timeline"><div :class="{done:true}"><b>1</b><span>Soumission</span></div><div :class="{done:selected.status !== 'pending'}"><b>2</b><span>Instruction BEG</span></div><div :class="{done:selected.status === 'active'}"><b>3</b><span>Activation</span></div></div><p v-if="selected.status === 'pending'" class="page-subtitle">Votre dossier a été transmis. L’équipe BEG doit en commencer l’instruction. Aucun accès métier n’est encore ouvert.</p><p v-else-if="selected.status === 'under_review'" class="page-subtitle">L’équipe BEG examine votre dossier. Vous pourrez être invité à apporter des compléments.</p><p v-else-if="selected.status === 'active'" class="alert success">Votre espace est activé. Vous pouvez maintenant accéder au module qualité.</p><p v-else-if="selected.status === 'rejected'" class="alert error">Votre demande n’a pas été retenue. Consultez le motif ci-dessous.</p><div v-if="selected.review_note" class="review-note"><strong>Message de l’équipe BEG</strong><p>{{ selected.review_note }}</p></div><dl class="application-summary"><dt>E-mail</dt><dd>{{ selected.email }}</dd><dt>Coordonnées</dt><dd>{{ selected.address }}, {{ selected.city }}<br>{{ selected.phone }}</dd><dt>Fonction déclarée</dt><dd>{{ selected.applicant_function }}</dd></dl><AppModal v-model="editing" title="Compléter mon dossier" eyebrow="DOSSIER OFFICINE" :busy="busy"><form class="correction-form form-body" @submit.prevent="save"><p v-if="error" role="alert" class="alert error">{{ error }}</p><label>Nom de l’officine<input v-model.trim="form.officine_name" required maxlength="180" /></label><div class="form-grid"><label>Ville<input v-model.trim="form.city" required maxlength="120" /></label><label>Téléphone<input v-model.trim="form.phone" required type="tel" pattern="[+0-9 ()\-]{6,40}" maxlength="40" /></label></div><label>Adresse<input v-model.trim="form.address" required maxlength="500" /></label><label>Fonction déclarée<input v-model.trim="form.applicant_function" required maxlength="120" /></label><label class="checkbox-label"><input v-model="form.consent" type="checkbox" required /><span>Je confirme l’exactitude des informations transmises et mon habilitation à soumettre ce dossier.</span></label><div><button type="button" class="button secondary" :disabled="busy" @click="editing = false">Annuler</button> <button class="button primary" :disabled="busy">{{ busy ? 'Envoi…' : 'Soumettre à nouveau' }}</button></div></form></AppModal><button v-if="selected.status === 'corrections_requested'" class="button primary self-start" @click="edit">Compléter mon dossier</button><button v-if="selected.status === 'active'" class="button primary self-start" @click="enter">Accéder à mon officine</button></div></section><p class="muted-note">L’activation du service BestPharma ne vaut ni autorisation d’exercice ni certification BPD.</p></template><p v-if="demoMode" class="muted-note">Simulation : <RouterLink class="text-link" to="/beg/inscriptions">passer à la vue d’instruction BEG →</RouterLink></p></div></template>
